using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class RestApiTools(HttpClient httpClient, ILogger<RestApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Fetch a resource from the REST API by path. Returns the JSON response body.")]
    public async Task<string> GetResource(
        [Description("API path to fetch, e.g. 'users/42' or 'posts?page=1'")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("GET /{Path}", path);
        var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Create a new resource via POST. Returns the created resource as JSON.")]
    public async Task<string> CreateResource(
        [Description("API path to post to, e.g. 'users' or 'posts'")] string path,
        [Description("JSON string representing the resource to create")] string jsonBody,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("POST /{Path}", path);
        var content = new StringContent(jsonBody, Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync(path, content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = true), Description("Delete a resource by path. Returns true if the deletion succeeded.")]
    public async Task<string> DeleteResource(
        [Description("API path of the resource to delete, e.g. 'users/42'")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("DELETE /{Path}", path);
        var response = await httpClient.DeleteAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return JsonSerializer.Serialize(new { deleted = true, path }, JsonOptions);
    }
}

