9. {
10.     private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };
11. 
12.     [McpServerTool, Description("Fetch a resource from the REST API by path. Returns the JSON response body.")]
13.     public async Task<string> GetResource(
14.         [Description("API path to fetch, e.g. 'users/42' or 'posts?page=1'")] string path,
15.         CancellationToken cancellationToken = default)
16.     {
17.         logger.LogInformation("GET /{Path}", path);
18.         var response = await httpClient.GetAsync(path, cancellationToken);
19.         response.EnsureSuccessStatusCode();
20.         return await response.Content.ReadAsStringAsync(cancellationToken);
21.     }
22. 
