24.     public async Task<string> CreateResource(
25.         [Description("API path to post to, e.g. 'users' or 'posts'")] string path,
26.         [Description("JSON string representing the resource to create")] string jsonBody,
27.         CancellationToken cancellationToken = default)
28.     {
29.         logger.LogInformation("POST /{Path}", path);
30.         var content = new StringContent(jsonBody, Encoding.UTF8, "application/json");
31.         var response = await httpClient.PostAsync(path, content, cancellationToken);
32.         response.EnsureSuccessStatusCode();
33.         return await response.Content.ReadAsStringAsync(cancellationToken);
34.     }
35. 
36.     [McpServerTool(Destructive = true), Description("Delete a resource by path. Returns true if the deletion succeeded.")]
37.     public async Task<string> DeleteResource(
38.         [Description("API path of the resource to delete, e.g. 'users/42'")] string path,
39.         CancellationToken cancellationToken = default)
40.     {
